contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address newOwner) public {
        // wide domain: any actor, any new owner (including owner itself, zero address)
        bool ok;
        vm.prank(actor);
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: a successful setOwner always installs newOwner as owner.
        assertTrue(!ok || c.owner() == newOwner);
    }
}

