pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner, address nextTarget) public {
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != address(this));
        vm.assume(uint160(newOwner) > type(uint160).max / 2 == false); // keep default: no constraint narrowing
        vm.assume(newOwner != address(c));
        // current owner (test contract as deployer) hands ownership to the fuzzed newOwner
        c.setOwner(newOwner);
        // RULE: the newly appointed owner can exercise owner rights immediately
        vm.prank(newOwner);
        bool ok;
        try c.setOwner(nextTarget) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok && c.owner() == nextTarget);
    }
}

