pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address mid, address finalOwner) public {
        vm.assume(mid != address(0));
        vm.assume(finalOwner != address(0));

        // current owner (the test contract) transfers ownership to `mid`
        vm.prank(address(this));
        c.setOwner(mid);

        // `mid` (now the owner) transfers ownership to `finalOwner`
        vm.prank(mid);
        c.setOwner(finalOwner);

        // General rule: a successful transfer by the current owner always sets
        // owner to the requested target. Chained transfers therefore yield
        // owner == finalOwner. The mutant rewrites owner to msg.sender inside
        // the modifier, so after the second call owner == mid, not finalOwner.
        assertTrue(c.owner() == finalOwner);
    }
}

